# MAP file version [Apr 2020]

# SIRAH force field
# Coarse grained models for Nucleoside-nPhos
# + Initial mapping: Machado in Nat Comm, 2017, 8:1503 [DOI: 10.1038/ncomms15031]
# + Klein et al. 2020

# ***** [ cAMP ]
> CGRES
  CGNAME   CMX
  ALLNAME  CMP
  MAP P       => PX
  MAP C5' C5* => C5X
  MAP C1' C1* => C1X
  MAP C2      => C2A
  MAP N1      => N1A
  MAP N6      => N6A

# ***** [ AMP ]
> CGRES
  CGNAME   AMX
  ALLNAME  AMP
  MAP P       => PX
  MAP C5' C5* => C5X
  MAP C1' C1* => C1X
  MAP C2      => C2A
  MAP N1      => N1A
  MAP N6      => N6A

# ***** [ ADP ]
> CGRES
  CGNAME   ADX
  ALLNAME  ADP
  MAP PB      => PXB
  MAP PA      => PXA
  MAP C5' C5* => C5X
  MAP C1' C1* => C1X
  MAP C2      => C2A
  MAP N1      => N1A
  MAP N6      => N6A

# ***** [ ATP ]
> CGRES
  CGNAME   ATX
  ALLNAME  ATP
  MAP PG      => PXG
  MAP PB      => PXB
  MAP PA      => PXA
  MAP C5' C5* => C5X
  MAP C1' C1* => C1X
  MAP C2      => C2A
  MAP N1      => N1A
  MAP N6      => N6A

# ***** [ cGMP ]
